package com.careerguidance.controller;
import com.careerguidance.dto.request.*; import com.careerguidance.dto.response.*; import com.careerguidance.entity.*; import com.careerguidance.exception.UnauthorizedException; import com.careerguidance.repository.UserRepository; import com.careerguidance.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") public class AdminAuthController { private final AuthService auth; private final UserRepository users; private final PasswordEncoder passwords; public AdminAuthController(AuthService a,UserRepository u,PasswordEncoder p){auth=a;users=u;passwords=p;}
 @PostMapping("/login") public JwtResponse login(@Valid @RequestBody LoginRequest r){ JwtResponse result=auth.login(r); if(!result.getRoles().contains("ROLE_ADMIN")) throw new UnauthorizedException("Administrator access required"); return result; }
 @GetMapping("/profile") @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") public StudentSummaryResponse profile(Authentication a){User u=users.findByEmail(a.getName()).orElseThrow(()->new UnauthorizedException("User not found"));return new StudentSummaryResponse(u.getId(),u.getFirstName(),u.getLastName(),u.getEmail(),u.getCollegeName(),u.getCgpa(),u.getActive());}
 @PutMapping("/change-password") @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") public MessageResponse change(@Valid @RequestBody ChangePasswordRequest r,Authentication a){User u=users.findByEmail(a.getName()).orElseThrow(()->new UnauthorizedException("User not found"));if(!passwords.matches(r.getCurrentPassword(),u.getPassword()))throw new UnauthorizedException("Current password is incorrect");u.setPassword(passwords.encode(r.getNewPassword()));users.save(u);return new MessageResponse("Password changed successfully");}}
